import React, { useState } from 'react';
import './SignUpForm.css'; // Import the CSS file

const SignUp = () => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
  });

  const { name, email, password } = formData;

  // Handles input changes
  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
    
  };
  // Validate input fields
  const validateField = (fieldName, value) => {
    let errorMsg = '';

    if (fieldName === 'name') {
      errorMsg = value.length < 3 ? 'Name must be at least 3 characters' : '';
    } else if (fieldName === 'email') {
      const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      errorMsg = !emailPattern.test(value) ? 'Enter a valid email address' : '';
    } else if (fieldName === 'password') {
      errorMsg = value.length < 6 ? 'Password must be at least 6 characters' : '';
    }

    setErrors((prevErrors) => ({ ...prevErrors, [fieldName]: errorMsg }));
  };

  // Function to register coach
  const registerCoach = async (e) => {
    e.preventDefault(); // Prevent page reload

    try {
      const response = await fetch('http://localhost:5000/api/auth/signup', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ name, email, password }),
      });

      const data = await response.json();
      console.log(data);

      if (data.token) {
        alert('Registration successful!');
      } else {
        alert(data.msg || 'Registration failed');
      }
    } catch (error) {
      console.error('Error registering coach:', error);
    }
  };

  return (
    <div className="signup-form"> {/* Add the className here */}
      <h2>Coach Sign-Up</h2>
      <form onSubmit={registerCoach}>
        <input
          type="text"
          name="name"
          placeholder="Name"
          value={name}
          onChange={handleChange}
          required
        />
        <input
          type="email"
          name="email"
          placeholder="Email"
          value={email}
          onChange={handleChange}
          required
        />
        <input
          type="password"
          name="password"
          placeholder="Password"
          value={password}
          onChange={handleChange}
          required
        />
        <button type="submit">Sign Up</button>
      </form>
    </div>
  );
};

export default SignUp;
